begin;
do $$
declare a uuid:=gen_random_uuid();s uuid:=gen_random_uuid();s2 uuid:=gen_random_uuid();u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();ap uuid:=gen_random_uuid();sp uuid:=gen_random_uuid();sp2 uuid:=gen_random_uuid();pp uuid:=gen_random_uuid();vp uuid:=gen_random_uuid();own uuid;pool uuid;other uuid;
begin
 insert into auth.users(id,email) values(a,'qa-staff-admin-'||a||'@example.invalid'),(s,'qa-staff-'||s||'@example.invalid'),(s2,'qa-staff-'||s2||'@example.invalid'),(u,'qa-staff-patient-'||u||'@example.invalid'),(v,'qa-staff-patient-'||v||'@example.invalid');
 insert into public.profiles(id,user_id,username,full_name,role) values(ap,a,'qa-'||a,'QA admin','admin'),(sp,s,'qa-'||s,'QA secretary','secretary'),(sp2,s2,'qa-'||s2,'QA secretary','secretary'),(pp,u,'qa-'||u,'QA patient','patient'),(vp,v,'qa-'||v,'QA patient','patient');
 insert into public.staff_permissions(user_id,view_tasks) values(s,true),(s2,true);
 insert into public.staff_tasks(patient_id,assigned_to,title,created_by) values(pp,s,'QA own',ap) returning id into own;
 insert into public.staff_tasks(patient_id,assigned_to,title,created_by) values(pp,null,'QA pool',ap) returning id into pool;
 insert into public.staff_tasks(patient_id,assigned_to,title,created_by) values(vp,s2,'QA other',ap) returning id into other;
 insert into public.clinical_records(patient_id,kind,payload,visibility,created_by) values(pp,'note','{"text":"QA shared but not for staff"}','shared',ap);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated','aal','aal1')::text,true);execute 'set local role authenticated';
 if (select count(*) from public.staff_tasks where id in(own,pool,other))<>2 then raise exception 'FAIL assigned/pool visibility';end if;
 if exists(select 1 from public.clinical_records where patient_id=pp) or exists(select 1 from public.profiles where id=pp) then raise exception 'FAIL clinical/patient profile leakage';end if;
 if public.staff_patient_label(pp)<>'QA patient' then raise exception 'FAIL label without contact capability';end if;
 begin perform public.staff_patient_label(vp);raise exception 'FAIL label other assignment';exception when insufficient_privilege then null;end;
 begin perform public.complete_staff_task(own);raise exception 'FAIL complete without capability';exception when insufficient_privilege then null;end;
 begin perform public.staff_patient_contact(pp);raise exception 'FAIL contact without capability';exception when insufficient_privilege then null;end;
 begin perform public.staff_schedule_appointment(pp,now()+interval '1 day','QA');raise exception 'FAIL schedule without capability';exception when insufficient_privilege then null;end;
 begin update public.staff_permissions set complete_tasks=true where user_id=s;if found then raise exception 'FAIL self permission escalation';end if;exception when insufficient_privilege then null;end;
 begin update public.profiles set role='admin' where id=sp;raise exception 'FAIL self role escalation';exception when insufficient_privilege then null;end;
 execute 'reset role';insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),s,'totp','verified',now(),now());execute 'set local role authenticated';
 if exists(select 1 from public.staff_tasks where id in(own,pool)) then raise exception 'FAIL staff MFA aal1';end if;
 begin perform public.staff_patient_label(pp);raise exception 'FAIL label MFA aal1';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated','aal','aal2')::text,true);
 if (select count(*) from public.staff_tasks where id in(own,pool))<>2 then raise exception 'FAIL staff MFA aal2';end if;
 execute 'reset role';update public.staff_permissions set complete_tasks=true,view_contact=true,schedule_appointments=true where user_id=s;execute 'set local role authenticated';
 begin perform public.complete_staff_task(other);raise exception 'FAIL complete other assignment';exception when insufficient_privilege then null;end;
 begin perform public.staff_patient_contact(vp);raise exception 'FAIL contact other assignment';exception when insufficient_privilege then null;end;
 begin perform public.staff_schedule_appointment(vp,now()+interval '1 day','QA');raise exception 'FAIL schedule other assignment';exception when insufficient_privilege then null;end;
 perform public.complete_staff_task(own);perform public.complete_staff_task(pool);perform public.staff_patient_contact(pp);perform public.staff_schedule_appointment(pp,now()+interval '1 day','QA');
 if exists(select 1 from public.staff_tasks where id in(own,pool) and status<>'completed') then raise exception 'FAIL authorized completion';end if;
 execute 'reset role';update public.staff_tasks set status='cancelled' where id in(own,pool);execute 'set local role authenticated';
 begin perform public.staff_patient_label(pp);raise exception 'FAIL label after cancellation';exception when insufficient_privilege then null;end;
 begin perform public.staff_patient_contact(pp);raise exception 'FAIL contact after cancellation';exception when insufficient_privilege then null;end;
 begin perform public.staff_schedule_appointment(pp,now()+interval '1 day','QA');raise exception 'FAIL schedule after cancellation';exception when insufficient_privilege then null;end;
 begin perform public.complete_staff_task(own);raise exception 'FAIL complete cancelled';exception when insufficient_privilege then null;end;
 execute 'reset role';update public.staff_permissions set view_tasks=false where user_id=s;execute 'set local role authenticated';
 if exists(select 1 from public.staff_tasks where id in(own,pool,other)) then raise exception 'FAIL disabled visibility';end if;
 begin perform public.staff_patient_contact(pp);raise exception 'FAIL contact with tasks disabled';exception when insufficient_privilege then null;end;
 execute 'reset role';insert into public.staff_permissions(user_id,view_tasks,complete_tasks,view_contact,schedule_appointments) values(u,true,true,true,true);insert into public.staff_tasks(patient_id,assigned_to,title,created_by) values(pp,u,'QA misconfigured patient assignment',ap);execute 'set local role authenticated';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated','aal','aal1')::text,true);
 begin perform public.staff_patient_label(pp);raise exception 'FAIL patient permissions label';exception when insufficient_privilege then null;end;
 begin perform public.staff_patient_contact(pp);raise exception 'FAIL patient permissions contact';exception when insufficient_privilege then null;end;
 begin perform public.staff_schedule_appointment(pp,now()+interval '1 day','QA');raise exception 'FAIL patient permissions schedule';exception when insufficient_privilege then null;end;
 if exists(select 1 from public.staff_tasks where patient_id in(pp,vp)) then raise exception 'FAIL patient sees staff tasks';end if;
 execute 'reset role';
end $$;
rollback;
select 'PASS secretary: capability gates, assigned/pool isolation, no clinical access, no self escalation, view_tasks revocation, patient denied' as result;
